CREATE INDEX "weld_joints_natural_joint_asc_idx" ON "weld_joints" USING btree ((case when "joint" is null or btrim("joint"::text) = '' then 1 else 0 end) asc,(lower(substring(coalesce("joint"::text, '') from '^[^0-9]*'))) asc nulls last,((substring(coalesce("joint"::text, '') from '[0-9]+'))::numeric) asc nulls first,(lower(substring(regexp_replace(coalesce("joint"::text, ''), '^[^0-9]*[0-9]+', '') from '^[^0-9]*'))) asc nulls last,((substring(regexp_replace(coalesce("joint"::text, ''), '^[^0-9]*[0-9]+', '') from '[0-9]+'))::numeric) asc nulls first,(lower(coalesce("joint"::text, ''))) asc nulls last,"line","joint","id") WHERE octet_length(coalesce("weld_joints"."joint", '')) <= 256 and octet_length(coalesce("weld_joints"."line", '')) <= 256;--> statement-breakpoint
